# Data recovery code was generated by Claude.

import re
import unicodedata

import numpy as np
import pandas as pd
import duckdb
from rapidfuzz import fuzz, process

from utils import parse_list_col

SEASON_ORDER = ["winter", "spring", "summer", "fall"]
START_COHORT = ("fall", 2022)
END_COHORT = ("summer", 2026)

# Source-material types, in the order they appear in the SQL query / output
MEDIA_TYPES = ['doujinshi', 'manhua', 'manhwa', 'novel', 'light_novel', 'manga', 'one_shot']
MEDIA_SUFFIXES = ['score', 'members', 'start_year', 'end_year']
ADAPTATION_COLUMNS = [f"{mt}_{suffix}" for mt in MEDIA_TYPES for suffix in MEDIA_SUFFIXES]

# Same columns (and order) as the SQL query in clean()
OUTPUT_COLUMNS = (
    ['anime', 'mal_id', 'source', 'cohort', 'genres', 'demographics', 'themes',
     'rating', 'score', 'wc', 'prequel_id']
    + ADAPTATION_COLUMNS
    + ['points']
)


def cohort_range(start=START_COHORT, end=END_COHORT) -> list[str]:
    """Chronological cohort strings, e.g. ['fall 2022', 'winter 2023', ..., 'summer 2026']."""
    cohorts = []
    year, s_idx = start[1], SEASON_ORDER.index(start[0])
    end_key = (end[1], SEASON_ORDER.index(end[0]))

    while (year, s_idx) <= end_key:
        cohorts.append(f"{SEASON_ORDER[s_idx]} {year}")
        s_idx += 1
        if s_idx == len(SEASON_ORDER):
            s_idx = 0
            year += 1

    return cohorts


def _cohort_mask(df: pd.DataFrame, cohort: str) -> pd.Series:
    return df['cohort'].astype(str).str.strip().str.lower() == cohort


MATCH_THRESHOLD = 88     # minimum token_sort_ratio on the base title (0-100)
REVIEW_BELOW = 95        # matches under this score are printed for manual review
AMBIGUITY_MARGIN = 3     # skip if a forecasting title's runner-up is within this many points

_ORDINAL_WORDS = {"second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6}
_ROMAN = {"ii": 2, "iii": 3, "iv": 4, "v": 5}


def _normalize_title(title) -> tuple[str, int, int]:
    """
    Returns (base_title, season_number, part_number).
    Season/part markers are pulled out of the string so that "Show 2nd Season",
    "Show Season 2", "Show S2" and "Show II" all share one base and season = 2.
    A missing marker counts as 1, so "Show" and "Show Season 1" agree.
    """
    s = unicodedata.normalize("NFKD", str(title))
    s = "".join(c for c in s if not unicodedata.combining(c)).lower()
    s = s.replace("&", " and ")
    s = re.sub(r"[^a-z0-9]+", " ", s).strip()

    season, part = 1, 1

    def pull(pattern, group_fn):
        nonlocal s
        m = re.search(pattern, s)
        if m is None:
            return None
        value = group_fn(m)
        s = (s[:m.start()] + " " + s[m.end():]).strip()
        return value

    # part first, so "season 2 part 2" is split correctly
    p = pull(r"\bpart (\d+)\b", lambda m: int(m.group(1)))
    if p is not None:
        part = p

    for pattern, fn in [
        (r"\b(\d+)(?:st|nd|rd|th) season\b", lambda m: int(m.group(1))),
        (r"\b(second|third|fourth|fifth|sixth) season\b", lambda m: _ORDINAL_WORDS[m.group(1)]),
        (r"\bseason (\d+)\b", lambda m: int(m.group(1))),
        (r"\bs(\d+)\b", lambda m: int(m.group(1))),
        (r"\b(ii|iii|iv|v)$", lambda m: _ROMAN[m.group(1)]),
        (r"(?<=[a-z]) ([2-9])$", lambda m: int(m.group(1))),
    ]:
        value = pull(pattern, fn)
        if value is not None:
            season = value
            break

    s = re.sub(r"\bseason\b", " ", s)          # leftover "final season" etc.
    s = re.sub(r"\s+", " ", s).strip()
    return s, season, part


def recover_data(eliminated_forecasting_df: pd.DataFrame,
                 eliminated_initial_df: pd.DataFrame) -> pd.DataFrame:
    """
    Recover rows that failed the exact-title join, for ONE cohort.

    Every forecasting title is compared against every initial title:
      1. Titles are normalized (case, accents, punctuation) and season/part markers
         are extracted. Two titles can only match if season AND part agree.
      2. The remaining base titles are scored with token_sort_ratio.
      3. Pairs below MATCH_THRESHOLD are discarded, and a forecasting title whose
         runner-up is within AMBIGUITY_MARGIN of its best is skipped (too risky).
      4. Matches are assigned one-to-one, best score first.

    Returns a DataFrame with exactly OUTPUT_COLUMNS ('anime' and 'points' come from
    forecasting, everything else from initial_df); empty if nothing matched.
    """
    empty = pd.DataFrame(columns=OUTPUT_COLUMNS)
    if eliminated_forecasting_df.empty or eliminated_initial_df.empty:
        return empty

    f_df = eliminated_forecasting_df.reset_index(drop=True)
    i_df = eliminated_initial_df.reset_index(drop=True)

    f_norm = [_normalize_title(t) for t in f_df['anime']]
    i_norm = [_normalize_title(t) for t in i_df['title']]

    scores = process.cdist(
        [n[0] for n in f_norm], [n[0] for n in i_norm],
        scorer=fuzz.token_sort_ratio, dtype=np.float32
    )

    # season/part must agree, otherwise the pair is impossible
    f_keys = np.array([(n[1], n[2]) for n in f_norm])
    i_keys = np.array([(n[1], n[2]) for n in i_norm])
    same_key = (f_keys[:, None, :] == i_keys[None, :, :]).all(axis=2)
    scores = np.where(same_key, scores, 0.0)

    # ambiguity guard
    top2 = np.sort(scores, axis=1)[:, -2:] if scores.shape[1] > 1 else None
    best = scores.max(axis=1)
    ambiguous = np.zeros(len(f_df), dtype=bool)
    if top2 is not None:
        ambiguous = (top2[:, 1] - top2[:, 0]) < AMBIGUITY_MARGIN
        ambiguous &= top2[:, 0] > 0

    candidates = [
        (scores[r, c], r, c)
        for r in range(scores.shape[0])
        if best[r] >= MATCH_THRESHOLD and not ambiguous[r]
        for c in [int(scores[r].argmax())]
    ]

    used_i, f_idx, i_idx, chosen_scores = set(), [], [], []
    for score, r, c in sorted(candidates, reverse=True):
        if c in used_i:
            continue
        used_i.add(c)
        f_idx.append(r)
        i_idx.append(c)
        chosen_scores.append(score)

    if not f_idx:
        return empty

    for score, r, c in zip(chosen_scores, f_idx, i_idx):
        if score < REVIEW_BELOW:
            print(f"    review ({score:.0f}): '{f_df.loc[r, 'anime']}' -> '{i_df.loc[c, 'title']}'")

    result = i_df.iloc[i_idx].reset_index(drop=True)
    result['anime'] = f_df.iloc[f_idx]['anime'].to_numpy()
    result['points'] = f_df.iloc[f_idx]['points'].to_numpy()

    return result[OUTPUT_COLUMNS]


def recover_all(eliminated_forecasting_df: pd.DataFrame,
                eliminated_initial_df: pd.DataFrame) -> pd.DataFrame:
    """Iterates over every cohort, restricts both eliminated pools, and calls recover_data()."""
    pool_f = eliminated_forecasting_df.copy()
    pool_i = eliminated_initial_df.copy()

    forecasting_has_cohort = 'cohort' in pool_f.columns
    if not forecasting_has_cohort:
        print("  forecasting_df has no 'cohort' column: only the initial side is "
              "restricted per cohort; recovered titles are removed from the pool as we go.")

    recovered_frames = []

    for cohort in cohort_range():
        cohort_i = pool_i[_cohort_mask(pool_i, cohort)]
        cohort_f = pool_f[_cohort_mask(pool_f, cohort)] if forecasting_has_cohort else pool_f

        if cohort_i.empty or cohort_f.empty:
            continue

        recovered = recover_data(cohort_f.copy(), cohort_i.copy())

        if list(recovered.columns) != OUTPUT_COLUMNS:
            raise ValueError(
                f"recover_data() returned the wrong columns for {cohort}: "
                f"{list(recovered.columns)}"
            )

        print(f"  {cohort}: recovered {len(recovered)} "
              f"({len(cohort_f)} forecasting / {len(cohort_i)} initial candidates)")

        if recovered.empty:
            continue

        recovered_frames.append(recovered)

        # A recovered row can't be matched again in a later cohort
        pool_f = pool_f[~pool_f['anime'].isin(recovered['anime'])]
        pool_i = pool_i[~pool_i['mal_id'].isin(recovered['mal_id'])]

    if not recovered_frames:
        return pd.DataFrame(columns=OUTPUT_COLUMNS)

    return pd.concat(recovered_frames, ignore_index=True)


def clean(forecasting_df, initial_df, week) -> None:
    print(f"Week {week}...")
    initial_df['title'] = initial_df['title'].str.strip()
    forecasting_df['anime'] = forecasting_df['anime'].str.strip()

    adaptation_select = ",\n            ".join(f"i.{col}" for col in ADAPTATION_COLUMNS)

    combined_df = duckdb.sql(f"""
        select
            f.anime,
            i.mal_id,
            i.source,
            i.cohort,
            i.genres,
            i.demographics,
            i.themes,
            i.rating,
            i.score,
            i.wc,
            i.prequel_id,
            {adaptation_select},
            f.points
        from forecasting_df f
        left join initial_df i on f.anime = i.title
    """).df()

    assert list(combined_df.columns) == OUTPUT_COLUMNS, "SQL columns drifted from OUTPUT_COLUMNS"

    matched_df = combined_df.dropna(subset=['mal_id'])

    # 1. Store the eliminated data from BOTH sides (anti-joins on the same exact-title key)
    eliminated_forecasting_df = forecasting_df[~forecasting_df['anime'].isin(initial_df['title'])]
    eliminated_initial_df = initial_df[~initial_df['title'].isin(forecasting_df['anime'])]

    # 6a. Missing rows pre-recovery
    missing_before = len(combined_df) - len(matched_df)
    print(f"Missing before recovery: {missing_before}/{len(combined_df)} forecasting rows")
    print(f"Unmatched initial_df rows: {len(eliminated_initial_df)}")

    # 2-5. Iterate cohorts, restrict, recover
    print("Recovering by cohort...")
    recovered_df = recover_all(eliminated_forecasting_df, eliminated_initial_df)

    # 6b. Missing rows post-recovery
    missing_after = missing_before - len(recovered_df)
    print(f"Recovered {len(recovered_df)} rows")
    print(f"Missing after recovery: {missing_after}/{len(combined_df)} forecasting rows")

    if recovered_df.empty:
        combined_df = matched_df.copy()
    else:
        combined_df = pd.concat([matched_df, recovered_df], ignore_index=True)

    print("Doing the rest of the cleaning...")

    combined_df['points'] = combined_df['points'].astype(str).str.replace(',', '').str.strip()
    combined_df['points'] = pd.to_numeric(combined_df['points'], errors='coerce')
    combined_df = combined_df.drop_duplicates(subset=['anime'], keep='first')

    lists = ['genres', 'demographics', 'themes']
    combined_df[lists] = combined_df[lists].map(parse_list_col)

    combined_df.to_parquet(f"data/forecasting/processed/week{week}_processed.parquet")
    print(f"Parquet saved for week {week}!")

def main() -> None:
    initial_df = pd.read_csv("data/raw/anime_data.csv")
    for i in range(13):
        forecasting_df = pd.read_csv(f"data/forecasting/raw/week{i+1}.csv", encoding_errors="replace")
        clean(forecasting_df, initial_df, i+1)

if __name__ == "__main__":
    main()